=== FILE: tb/crc8_block_tb.v ===
// Self-checking constrained-random testbench for crc8_block.
// Expected values come from interface_spec.md (sections 2.1-2.3), not from the RTL.
// Verdict: one line "NIRMAAN-SIM <nonce> <n> passed, <m> failed", then $finish.
`timescale 1ns / 1ps
module crc8_block_tb;
    reg        clk;
    reg        rst_n;
    reg        init;
    reg        valid;
    reg  [7:0] data;
    wire [7:0] crc;

    crc8_block dut (
        .clk(clk), .rst_n(rst_n), .init(init),
        .valid(valid), .data(data), .crc(crc)
    );

    initial clk = 1'b0;
    always #5 clk = ~clk;

    integer pass_count;
    integer fail_count;
    reg [7:0]  model;            // running value per spec (crc = ~model)
    reg [7:0]  tbl [0:255];      // second, independently built model (byte-table form)
    reg [31:0] rng;
    reg [31:0] seed;
    reg [8*128-1:0] nonce;
    reg        nonce_found;
    reg [7:0]  ch;
    reg [7:0]  prev;
    reg [7:0]  t;
    reg        r_b, i_b, v_b;
    reg [7:0]  d_b;
    integer k, s, d, n;
    integer model_bad;
    integer rst_pm, init_pm, valid_pm, corner_pm;
    integer frame_len, max_frame;
    integer c_init_valid, c_rst_mid, c_rst_init, c_hold, c_b00, c_bFF, c_long, c_bytes;

    // Spec 2.2, literally: for bit 7 down to 0, XOR the bit into the top bit,
    // shift left by one, and if the bit shifted out was 1, XOR with 0x07.
    function [7:0] spec_step;
        input [7:0] sv;
        input [7:0] dv;
        integer i;
        reg [7:0] r;
        reg out;
        begin
            r = sv;
            for (i = 7; i >= 0; i = i - 1) begin
                r[7] = r[7] ^ dv[i];
                out  = r[7];
                r    = {r[6:0], 1'b0};
                if (out)
                    r = r ^ 8'h07;
            end
            spec_step = r;
        end
    endfunction

    // xorshift32: repeatable stimulus source held in the testbench.
    task rnd;
        begin
            rng = rng ^ (rng << 13);
            rng = rng ^ (rng >> 17);
            rng = rng ^ (rng << 5);
        end
    endtask

    task check_crc;
        input [7:0] exp;
        input integer id;
        begin
            if (crc === exp)
                pass_count = pass_count + 1;
            else begin
                fail_count = fail_count + 1;
                if (fail_count <= 10)
                    $display("TB: MISMATCH id=%0d t=%0t rst_n=%b init=%b valid=%b data=%h crc=%h expected=%h",
                             id, $time, rst_n, init, valid, data, crc, exp);
            end
        end
    endtask

    task check_cond;
        input ok;
        input integer id;
        begin
            if (ok)
                pass_count = pass_count + 1;
            else begin
                fail_count = fail_count + 1;
                $display("TB: CHECK FAILED id=%0d t=%0t", id, $time);
            end
        end
    endtask

    // Model update at a rising edge, per spec 2.1 / 2.2.
    task model_edge;
        begin
            if (!rst_n)
                model = 8'hFF;                       // CRC-RESET
            else if (init)
                model = 8'hFF;                       // CRC-INIT (reload wins)
            else if (valid)
                model = spec_step(model, data);      // CRC-POLY / CRC-ORDER
            // else hold                             // CRC-HOLD
        end
    endtask

    // One clock: drive on the falling edge, check that crc did not move without
    // an edge, then check after the rising edge against the model (CRC-FINAL).
    task do_cycle;
        input r;
        input i;
        input v;
        input [7:0] dd;
        input integer id;
        begin
            @(negedge clk);
            rst_n = r; init = i; valid = v; data = dd;
            #1 check_crc(~model, id + 1000);
            @(posedge clk);
            model_edge;
            #1 check_crc(~model, id);
        end
    endtask

    task run_phase;
        input integer cycles;
        input integer id;
        integer j;
        begin
            for (j = 0; j < cycles; j = j + 1) begin
                rnd; r_b = !((rng % 1000) < rst_pm);
                rnd; i_b =  ((rng % 1000) < init_pm);
                rnd; v_b =  ((rng % 1000) < valid_pm);
                rnd;
                if ((rng % 1000) < corner_pm) begin
                    rnd;
                    case (rng % 6)
                        0: d_b = 8'h00;
                        1: d_b = 8'hFF;
                        2: d_b = 8'h80;
                        3: d_b = 8'h01;
                        4: d_b = 8'h7F;
                        default: d_b = 8'hFE;
                    endcase
                end else begin
                    rnd; d_b = rng[15:8];
                end
                // corner accounting, from the spec's view of the inputs
                if (!r_b && v_b && frame_len > 0) c_rst_mid = c_rst_mid + 1;
                if (!r_b && i_b)                  c_rst_init = c_rst_init + 1;
                if (r_b && i_b && v_b)            c_init_valid = c_init_valid + 1;
                if (r_b && !i_b && !v_b && frame_len > 0) c_hold = c_hold + 1;
                if (r_b && !i_b && v_b) begin
                    c_bytes = c_bytes + 1;
                    if (d_b == 8'h00) c_b00 = c_b00 + 1;
                    if (d_b == 8'hFF) c_bFF = c_bFF + 1;
                    frame_len = frame_len + 1;
                    if (frame_len == 32) c_long = c_long + 1;
                    if (frame_len > max_frame) max_frame = frame_len;
                end
                if (!r_b || i_b) frame_len = 0;
                do_cycle(r_b, i_b, v_b, d_b, id);
            end
        end
    endtask

    initial begin
        pass_count = 0; fail_count = 0;
        rst_n = 1'b0; init = 1'b0; valid = 1'b0; data = 8'h00;
        model = 8'hFF;
        frame_len = 0; max_frame = 0;
        c_init_valid = 0; c_rst_mid = 0; c_rst_init = 0; c_hold = 0;
        c_b00 = 0; c_bFF = 0; c_long = 0; c_bytes = 0;

        seed = 32'h1F2E3D4C;
        if ($value$plusargs("tb_seed=%d", seed)) begin end
        if (seed == 32'd0) seed = 32'h1F2E3D4C;
        rng = seed;
        $display("TB: seed=%0d", seed);

        nonce = 0;
        nonce_found = 1'b0;
        if ($value$plusargs("NIRMAAN_NONCE=%s", nonce))      nonce_found = 1'b1;
        else if ($value$plusargs("nirmaan_nonce=%s", nonce)) nonce_found = 1'b1;
        else if ($value$plusargs("NONCE=%s", nonce))         nonce_found = 1'b1;
        else if ($value$plusargs("nonce=%s", nonce))         nonce_found = 1'b1;

        // Model self-check: byte-table model built from the polynomial alone,
        // compared with the bit-serial spec model over every (state, byte) pair.
        for (s = 0; s < 256; s = s + 1) begin
            t = s;
            repeat (8) t = t[7] ? ({t[6:0], 1'b0} ^ 8'h07) : {t[6:0], 1'b0};
            tbl[s] = t;
        end
        model_bad = 0;
        for (s = 0; s < 256; s = s + 1)
            for (d = 0; d < 256; d = d + 1)
                if (spec_step(s, d) !== tbl[(s ^ d) & 255]) model_bad = model_bad + 1;
        check_cond(model_bad == 0, 2);
        check_cond(tbl[8'h01] == 8'h07, 3);
        check_cond(tbl[8'h80] == 8'h89, 4);
        check_cond(tbl[8'hFF] == 8'hF3, 5);
        check_cond(tbl[8'h7F] == 8'h7A, 6);

        // D1: reset, then CRC-RESET / CRC-EMPTY
        @(posedge clk);
        @(posedge clk);
        model = 8'hFF;
        #1 check_crc(8'h00, 1);
        check_crc(~model, 1);

        // D2: hand-computed anchors, one byte after a reload (CRC-POLY, CRC-ORDER)
        do_cycle(1'b1, 1'b1, 1'b0, 8'h00, 20); check_crc(8'h00, 19);
        do_cycle(1'b1, 1'b0, 1'b1, 8'h00, 21); check_crc(8'h0C, 22);
        do_cycle(1'b1, 1'b1, 1'b0, 8'h00, 23);
        do_cycle(1'b1, 1'b0, 1'b1, 8'hFF, 24); check_crc(8'hFF, 25);
        do_cycle(1'b1, 1'b1, 1'b0, 8'h00, 26);
        do_cycle(1'b1, 1'b0, 1'b1, 8'h80, 27); check_crc(8'h85, 28);
        do_cycle(1'b1, 1'b1, 1'b0, 8'h00, 29);
        do_cycle(1'b1, 1'b0, 1'b1, 8'h01, 30); check_crc(8'h0B, 31);

        // D3: init wins over a byte offered at the same edge (CRC-INIT)
        do_cycle(1'b1, 1'b0, 1'b1, 8'h5A, 40);
        do_cycle(1'b1, 1'b0, 1'b1, 8'hC3, 41);
        do_cycle(1'b1, 1'b1, 1'b1, 8'hA5, 42); check_crc(8'h00, 43);

        // D4: hold with valid low and changing data (CRC-HOLD)
        do_cycle(1'b1, 1'b0, 1'b1, 8'h96, 50);
        prev = crc;
        repeat (5) begin
            rnd;
            do_cycle(1'b1, 1'b0, 1'b0, rng[7:0], 51);
            check_crc(prev, 52);
        end

        // D5: reset during a frame with a byte offered (CRC-RESET priority)
        do_cycle(1'b1, 1'b0, 1'b1, 8'h3C, 60);
        do_cycle(1'b0, 1'b0, 1'b1, 8'h3C, 61); check_crc(8'h00, 62);

        // D6: reset together with init and valid; then first byte after release
        do_cycle(1'b1, 1'b0, 1'b1, 8'h11, 70);
        do_cycle(1'b0, 1'b1, 1'b1, 8'h22, 71); check_crc(8'h00, 72);
        do_cycle(1'b1, 1'b0, 1'b1, 8'h00, 73); check_crc(8'h0C, 74);
        frame_len = 1;

        // R1: dense resets/reloads, corner-biased data
        rst_pm = 30; init_pm = 80; valid_pm = 600; corner_pm = 300;
        run_phase(3000, 100);
        // R2: knobs eased for long frames
        rst_pm = 3; init_pm = 10; valid_pm = 850; corner_pm = 150;
        run_phase(3000, 200);

        $display("TB: bytes=%0d init_valid=%0d rst_mid=%0d rst_init=%0d hold=%0d b00=%0d bFF=%0d long32=%0d max_frame=%0d",
                 c_bytes, c_init_valid, c_rst_mid, c_rst_init, c_hold, c_b00, c_bFF, c_long, max_frame);
        // Coverage goals: the run fails itself when stimulus fell short.
        check_cond(c_init_valid >= 20, 900);
        check_cond(c_rst_mid    >= 5,  901);
        check_cond(c_rst_init   >= 1,  902);
        check_cond(c_hold       >= 200, 903);
        check_cond(c_b00        >= 10, 904);
        check_cond(c_bFF        >= 10, 905);
        check_cond(c_long       >= 3,  906);
        check_cond(max_frame    >= 64, 907);

        if (!nonce_found) begin
            nonce = "NONCE_MISSING";
            fail_count = fail_count + 1;
            $display("TB: run nonce plusarg not found");
        end

        $write("NIRMAAN-SIM ");
        for (k = 127; k >= 0; k = k - 1) begin
            ch = nonce[k*8 +: 8];
            if (ch != 8'h00) $write("%c", ch);
        end
        $display(" %0d passed, %0d failed", pass_count, fail_count);
        $finish;
    end
endmodule
=== END FILE ===
